  return (
    <div className="my-2 flex justify-center">
      <span className="rounded-[8px] bg-[var(--wa-pill)] px-3 py-[5px] text-[12px] font-medium uppercase tracking-wide text-[var(--wa-muted)] shadow-[0_1px_0.5px_rgba(11,20,26,0.13)]">
        {text}
