          <span className={cx("text-[16px]", variant === "ios" ? "font-semibold" : "font-medium")}>
            {message.buttonLabel}
          </span>
        </div>
        <div className="max-h-[520px] overflow-hidden pb-6">
          {(message.sections ?? []).map((section, si) => (
            <div key={si}>
              {section.title && (
                <div className="px-5 pb-1 pt-4 text-[13px] font-medium text-[var(--wa-accent)]">{section.title}</div>
              )}
              {section.rows.map((row, ri) => {
                const selected = row.title === message.selected
                return (
                  <div key={ri} className="flex items-center gap-3 px-5 py-2.5">
                    <div className="min-w-0 flex-1">
                      <div className="text-[15.5px]">{row.title}</div>
                      {row.description && <div className="text-[13px] text-[var(--wa-muted)]">{row.description}</div>}
                    </div>
                    <span
                      className={cx(
                        "flex h-[20px] w-[20px] shrink-0 items-center justify-center rounded-full border-2",
                        selected ? "border-[var(--wa-accent)]" : "border-[var(--wa-muted)]",
                      )}
                    >
                      {selected && <span className="h-[10px] w-[10px] rounded-full bg-[var(--wa-accent)]" />}
                    </span>
                  </div>
                )
              })}
            </div>
          ))}
        </div>
        {message.selected && (
          <div className="absolute bottom-6 right-5">
            <span className="flex h-[52px] w-[52px] items-center justify-center rounded-full bg-[var(--wa-accent)] text-white shadow-lg">
              <Send size={22} />
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

import { Fragment, type ReactNode } from "react"

/**
 * Renders WhatsApp-style formatting:
 * *bold*  _italic_  ~strike~  `inline code`  ```monospace```  and bare links.
 */

const BLOCK = /```([\s\S]+?)```/g
const LINK = /(https?:\/\/[^\s]+|www\.[^\s]+)/g
// A marker must touch a non-space character on the inside, like WhatsApp does.
const INLINE = /(^|[^\w])([*_~`])(?!\s)([^\n]*?[^\s\\])\2(?![\w])/

const tags: Record<string, (children: ReactNode, key: number) => ReactNode> = {
  "*": (c, k) => (
    <strong key={k} className="font-semibold">
      {c}
    </strong>
  ),
  _: (c, k) => <em key={k}>{c}</em>,
  "~": (c, k) => <s key={k}>{c}</s>,
  "`": (c, k) => (
    <code key={k} className="rounded bg-[var(--wa-divider)] px-1 font-mono text-[0.92em]">
      {c}
    </code>
  ),
}

/** Lets long URLs wrap after each "/" like WhatsApp does. */
export function BreakAfterSlashes({ text }: { text: string }) {
  return (
    <>
      {text.split(/(?<=\/)/).map((piece, j) => (
        <Fragment key={j}>
          {j > 0 && <wbr />}
          {piece}
        </Fragment>
      ))}
    </>
  )
}

function links(text: string, keyBase: string): ReactNode[] {
  return text.split(LINK).map((part, i) =>
    i % 2 === 1 ? (
      <span key={`${keyBase}-l${i}`} className="text-[var(--wa-link)] underline decoration-1 underline-offset-[3px]">
        <BreakAfterSlashes text={part} />
      </span>
    ) : (
      <Fragment key={`${keyBase}-t${i}`}>{part}</Fragment>
    ),
  )
}

function inline(text: string, keyBase = "f"): ReactNode[] {
  const out: ReactNode[] = []
  let rest = text
  let n = 0
  while (rest) {
    const m = INLINE.exec(rest)
    if (!m) {
      out.push(...links(rest, `${keyBase}${n}`))
      break
    }
    const [whole, before, marker, inner] = m
    out.push(...links(rest.slice(0, m.index) + before, `${keyBase}${n}`))
    const children = marker === "`" ? inner : inline(inner, `${keyBase}${n}i`)
    out.push(tags[marker](children, n))
    rest = rest.slice(m.index + whole.length)
    n++
  }
  return out
}

export function FormattedText({ text }: { text: string }) {
  const parts: ReactNode[] = []
  let last = 0
  let i = 0
  for (const m of text.matchAll(BLOCK)) {
    parts.push(<Fragment key={`p${i}`}>{inline(text.slice(last, m.index), `p${i}`)}</Fragment>)
    parts.push(
      <code key={`b${i}`} className="font-mono text-[0.92em]">
        {m[1]}
      </code>,
    )
    last = (m.index ?? 0) + m[0].length
    i++
  }
  parts.push(<Fragment key="end">{inline(text.slice(last), "e")}</Fragment>)
  return <>{parts}</>
}

import type { SVGProps } from "react"

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

function Svg({ size = 24, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      {...props}
    >
      {children}
    </svg>
  )
}

